/**
 * Bubble Sort implementation for sorting an array of integers
 * Sorts the array in ascending order
 * 
 * @param {number[]} arr - Array of integers to sort
 * @returns {number[]} - A new sorted array (original array is not mutated)
 * 
 * Algorithm Logic:
 * 1. Iterates through the array multiple times (passes)
 * 2. Compares adjacent elements in each pass
 * 3. Swaps elements if they are in wrong order (left > right)
 * 4. Largest unsorted elements "bubble" to their correct position at the end each pass
 * 5. Reduces the comparison range each pass since last elements are sorted
 * 6. Optimizes by stopping early if a complete pass requires no swaps (already sorted)
 * 
 * Time Complexity:
 * - Worst Case: O(n²) - when array is sorted in descending order
 * - Average Case: O(n²) - random order
 * - Best Case: O(n) - when array is already sorted (early exit)
 * 
 * Space Complexity:
 * - O(1) - sorts in-place, uses constant extra space
 */
function bubbleSort(arr) {
  // Input validation
  if (!Array.isArray(arr)) {
    throw new Error('Input must be an array');
  }

  // Check array length constraint
  if (arr.length > 100) {
    throw new Error(`Input array length (${arr.length}) exceeds maximum limit of 100 elements`);
  }

  // Validate each element in the array
  for (let i = 0; i < arr.length; i++) {
    if (typeof arr[i] !== 'number') {
      throw new Error(`Element at index ${i} is not a number: ${arr[i]}`);
    }

    if (!Number.isInteger(arr[i])) {
      throw new Error(`Element at index ${i} is not an integer: ${arr[i]}`);
    }

    if (arr[i] < -10000 || arr[i] > 10000) {
      throw new Error(`Element at index ${i} (${arr[i]}) is out of range [-10,000, 10,000]`);
    }
  }

  // Main bubble sort logic with error handling
  try {
    const n = arr.length;

    // Create a copy to avoid mutating the original array
    const sortedArray = [...arr];

    // Outer loop: controls the number of passes
    for (let i = 0; i < n - 1; i++) {
      let swapped = false; // Optimization flag to detect if array is sorted

      // Inner loop: performs comparisons and swaps
      // n - 1 - i: reduces range as last i elements are already sorted
      for (let j = 0; j < n - 1 - i; j++) {
        // Compare adjacent elements
        if (sortedArray[j] > sortedArray[j + 1]) {
          // Swap elements using destructuring assignment
          [sortedArray[j], sortedArray[j + 1]] = [sortedArray[j + 1], sortedArray[j]];
          swapped = true;
        }
      }

      // Early exit optimization: if no swaps were made, array is already sorted
      if (!swapped) {
        break;
      }
    }

    return sortedArray;

  } catch (error) {
    // Re-throw with additional context
    throw new Error(`Failed to sort array: ${error.message}`);
  }
}

// Example usage and test cases
