            Object.entries(cities).forEach(([cityId, config]) => {
                const now = moment().tz(config.timezone);
                const timeElement = document.getElementById(`${cityId}-time`);
                const dateElement = document.getElementById(`${cityId}-date`);

                // Setup time display based on 12 or 24-hour format
                let timeStr;
                if (config.format12) {
                    timeStr = now.format('h:mm:ss A');
                } else {
                    timeStr = now.format('HH:mm:ss');
                }

                // Update seconds indicator
                const secondsIndicator = '<span class="seconds-indicator"></span>';
                timeElement.innerHTML = timeStr + secondsIndicator;

                // Update date display with day of week
                dateElement.textContent = now.format('dddd, MMMM D, YYYY');
            });
        }

        // Initialize clocks immediately
        updateClocks();

        // Update clocks every second
        setInterval(updateClocks, 1000);

        // Initialize clocks when page loads
        window.addEventListener('load', () => {
            // Initial update
            updateClocks();

            // Add a visual indicator that clocks are running
            console.log('World clocks initialized and running...');
        });
    </script>
</body>
</html>
