            grid.innerHTML = '';

            const filteredArtifacts = artifacts.filter(artifact => {
                const matchesFilter = currentFilter === 'all' || artifact.category === currentFilter;
                const matchesSearch = artifact.name.toLowerCase().includes(query) ||
                    artifact.period.toLowerCase().includes(query) ||
                    artifact.location.toLowerCase().includes(query) ||
                    artifact.description.toLowerCase().includes(query);

                return matchesFilter && matchesSearch;
            });

